package com.circlenet.domain.trust;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="emergency_access_requests") public class EmergencyAccessRequestEntity {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="owner_user_id",nullable=false) private Long ownerUserId;@Column(name="requester_user_id",nullable=false) private Long requesterUserId;@Column(nullable=false,length=1000) private String reason;@Column(nullable=false,length=20) private String status="PENDING";@Column(name="required_approvals",nullable=false) private int requiredApprovals=2;@Column(name="created_at",nullable=false) private Instant createdAt=Instant.now();@Column(name="expires_at",nullable=false) private Instant expiresAt;@Column(name="granted_until") private Instant grantedUntil;public Long getId(){return id;}public Long getOwnerUserId(){return ownerUserId;}public void setOwnerUserId(Long v){ownerUserId=v;}public Long getRequesterUserId(){return requesterUserId;}public void setRequesterUserId(Long v){requesterUserId=v;}public String getReason(){return reason;}public void setReason(String v){reason=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public int getRequiredApprovals(){return requiredApprovals;}public void setRequiredApprovals(int v){requiredApprovals=v;}public Instant getCreatedAt(){return createdAt;}public Instant getExpiresAt(){return expiresAt;}public void setExpiresAt(Instant v){expiresAt=v;}public Instant getGrantedUntil(){return grantedUntil;}public void setGrantedUntil(Instant v){grantedUntil=v;}}
